c(){ curl -sSLG --compressed -A "Mozilla/5.0" "$@"; }; [ -n "$F" ] || { printf "Nom de ce fournisseur : "; read -r F; }; [ -n "$U" ] || { printf "Adresse du serveur (ex. http://monserveur.com:8080) : "; read -r U; }; [ -n "$N" ] || { printf "Nom d'utilisateur : "; read -r N; }; printf "Mot de passe de %s chez %s (il ne s'affiche pas quand tu tapes) : " "$N" "$F"; read -rs P; echo; case "$U" in http*) ;; *) U="http://$U";; esac; U="${U%%/get.php*}"; U="${U%%/player_api.php*}"; U="${U%/}"; MS=$(c "$U/player_api.php" --data-urlencode "username=$N" --data-urlencode "password=$P" -o /dev/null -w "%{time_total}"); R=$(c "$U/player_api.php" --data-urlencode "username=$N" --data-urlencode "password=$P"); case "$R" in *'"auth":1'*|*'"auth": 1'*|*'"auth":"1"'*) echo "✓ Connexion acceptée";; *) echo "⚠ Le serveur refuse la connexion ou répond autre chose. Début de la réponse :"; echo "${R:0:200}";; esac; D=~/Desktop/prisme-"${F// /-}"; mkdir -p "$D" && cd "$D" && printf '%s' "$R" | MS="$MS" HOSTU="$U" perl -MJSON::PP -0777 -e 'my $j = eval { JSON::PP->new->utf8->decode(<STDIN>) } || {}; delete $j->{user_info}{password} if ref $j->{user_info} eq "HASH"; $j->{ms} = int(($ENV{MS} || 0) * 1000); $j->{at} = time; $j->{host} = $ENV{HOSTU}; print JSON::PP->new->utf8->canonical->encode($j)' > compte.json; echo "✓ compte : $(head -c 120 compte.json)"; for a in get_live_categories get_live_streams get_vod_categories get_vod_streams get_series_categories get_series; do c "$U/player_api.php" --data-urlencode "username=$N" --data-urlencode "password=$P" --data-urlencode "action=$a" -o "$a.json"; echo "✓ $a : $(wc -c < "$a.json" | tr -d ' ') octets, début : $(head -c 60 "$a.json")"; done; c "$U/xmltv.php" --data-urlencode "username=$N" --data-urlencode "password=$P" -o xmltv.xml; echo "✓ guide : $(wc -c < xmltv.xml | tr -d ' ') octets";